def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ' + target + ' ') and 'pick up' in obs:
        nb['target_in_hand'] = True
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and act.startswith('put ' + target + ' ') and 'you put' in obs:
        nb['target_in_hand'] = False
    pc = val(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target and act.startswith('put ' + target + ' ') and 'you put' in obs and (not dest or dest in act):
        old = nb.get('placed_count', 0)
        try:
            old = int(old)
        except Exception:
            old = 0
        if pc < old + 1:
            pc = old + 1
    nb['placed_count'] = pc
    locs = val(ctx, 'world.placed_locations', [])
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and target and target not in inv and 'not carrying' not in inv and 'nothing' not in inv)
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and target and dest and act.startswith('put ' + target + ' ') and dest in act and 'you put' in obs:
        stage = 'done'
    elif carrying and target:
        stage = 'put_target'
    elif target and pc > 0 and pc < 2:
        stage = 'find_target'
    elif target:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

