def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb', '')
    tt = nb.get('task_type', '')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory appears to hold a non-target object. Do not place it at the destination; recover by setting it aside if needed, then find the requested target type.'
    elif stage == 'transform' and verb:
        msg = 'Before final placement, use the admissible ' + verb + ' action on the carried ' + target + ' at the proper appliance or basin. Do not put the untransformed target at the destination yet.'
    elif stage == 'put_target' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the admissible put action there. Do not substitute another object type.'
    elif stage == 'find_target' and target and 'two' in tt and val(ctx, 'world.placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same destination type.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

