    return ''

def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb', '')
    tt = nb.get('task_type', '')
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not act:
        return None
    if target and dest and act.startswith('put ' + target + ' ') and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Keep the target and carry it to a ' + dest + ' instead of placing it elsewhere.'}
    if target and verb and not nb.get('transformed') and act.startswith('put ' + target + ' '):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First use the admissible ' + verb + ' action on it, then carry it to the requested destination.'}
    if target and 'two' in tt and act.startswith('take ' + target + ' '):
        locs = nb.get('placed_locations') or []
        for loc in locs:
            if loc and loc in act:
                return {'kind': 'block_and_prompt', 'message': 'Do not take back a target that is already placed. Find another target of the same type and use the same destination.'}
    return None
